  ["majid", "Ali Hassan al-Majid", "Iraq", "Northern Bureau chief 1987-1989", "hrw", "Saddam's cousin, known as Chemical Ali. Given sweeping powers over northern Iraq in 1987, he directed the Anfal campaign against the Kurds."],
  ["aziz", "Tariq Aziz", "Iraq", "Foreign minister 1983-1991", "ebb82", "Saddam's foreign minister and later deputy prime minister. Washington's main Iraqi contact during the 1980s tilt toward Baghdad."],
  ["kamel", "Hussein Kamel", "Iraq", "Weapons chief, defected 1995", "duelfer", "Saddam's son-in-law and head of Iraq's military industries. His 1995 defection exposed the biological weapons program."],
  ["chalabi", "Ahmed Chalabi", "Iraq", "Iraqi National Congress", "ssciInc", "Exiled founder of the Iraqi National Congress, who lobbied Washington for regime change and supplied defectors to US intelligence."],
  ["maliki", "Nouri al-Maliki", "Iraq", "Prime minister 2006-2014", "lejeune", "Prime minister of Iraq from May 2006 through the sectarian war and the US withdrawal."],
  ["talabani", "Jalal Talabani", "Kurdistan", "PUK leader, president of Iraq 2005-2014", "hrw", "Founded the Patriotic Union of Kurdistan in 1975 and led it through the Anfal years. Became Iraq's first Kurdish president in 2005."],
  ["mbarzani", "Mustafa Barzani", "Kurdistan", "KDP leader, died 1979", "frus27", "Led the Kurdish revolt from 1961. Took secret US and Iranian aid from 1972 and lost it in 1975 when the Shah made peace with Saddam."],
  ["curveball", "Curveball", "Iraq", "Informant, 1999-2004", "robb", "Codename of an Iraqi defector in Germany whose claims about mobile bioweapons labs went into Powell's UN speech. The claims were fabricated."],
  ["shah", "Mohammad Reza Shah", "Iran", "Shah 1941-1979", "frus77rev", "Shah of Iran, restored by the 1953 coup and Washington's main Gulf ally until the 1979 revolution."],
  ["mosaddegh", "Mohammad Mosaddegh", "Iran", "Prime minister 1951-1953", "ebb435", "Iran's elected prime minister who nationalized the country's oil. Overthrown by the CIA and MI6 in 1953."],
  ["khomeini", "Ayatollah Khomeini", "Iran", "Supreme Leader 1979-1989", "frus77rev", "Exiled in 1964, he spent years in Najaf, Iraq, before leading the 1979 revolution. Led Iran through the war with Iraq."],
  ["najibullah", "Mohammad Najibullah", "Afghanistan", "President 1986-1992", "ebb57", "Afghanistan's last communist leader. His government outlasted the Soviet withdrawal until 1992. Killed by the Taliban in 1996."],
  ["karzai", "Hamid Karzai", "Afghanistan", "Leader 2001-2014", "bonn", "Chosen at the December 2001 Bonn conference to lead Afghanistan's interim government after the Taliban fell."],
  ["zia", "Zia ul-Haq", "Pakistan", "Ruler 1977-1988", "ebb57", "Pakistan's military ruler, whose intelligence service handled US and Saudi aid to the Afghan mujahideen."],
  ["brezhnev", "Leonid Brezhnev", "Soviet Union", "Soviet leader 1964-1982", "ebb57", "Signed the 1972 friendship treaty with Iraq and ordered the 1979 invasion of Afghanistan."],
  ["begin", "Menachem Begin", "Israel", "Prime minister 1977-1983", "unsc487", "Israeli prime minister who ordered the June 1981 strike on Iraq's Osirak reactor."],
  ["churchill", "Winston Churchill", "Britain", "Prime minister 1951-1955", "ebb435", "His government pressed for Mosaddegh's removal after Iran nationalized British oil and brought the coup plan to Washington."],
  ["blair", "Tony Blair", "Britain", "Prime minister 1997-2007", "chilcot", "Bush's closest ally on Iraq. The Chilcot inquiry found he presented the threat from Iraqi weapons with a certainty that was not justified."],
  ["eisenhower", "Dwight Eisenhower", "United States", "President 1953-1961", "eisdoc", "Approved the 1953 Iran coup, launched Atoms for Peace, and pledged to defend Middle Eastern states against communism."],
  ["kroosevelt", "Kermit Roosevelt Jr.", "United States", "CIA officer, Near East", "ebb28", "Grandson of Theodore Roosevelt and head of CIA operations in the Near East. Ran the 1953 coup against Mosaddegh on the ground in Tehran."],
  ["archie", "Archie Roosevelt Jr.", "United States", "CIA officer, 1947-1974", "archieMemoir", "Kermit Roosevelt's cousin and a CIA Middle East specialist. Worked on the 1956 plot to overthrow Syria's government, then rose to senior CIA posts. Wrote the memoir For Lust of Knowing (1988)."],
  ["jfk", "John F. Kennedy", "United States", "President 1961-1963", "frus63", "His administration watched Qasim warily and quickly welcomed the Ba'athist government after the 1963 coup."],
  ["nixon", "Richard Nixon", "United States", "President 1969-1974", "frusE4", "Made the Shah his regional enforcer and in 1972 approved secret aid to Iraq's Kurds."],
  ["kissinger", "Henry Kissinger", "United States", "NSA and Secretary of State 1969-1977", "frus27", "Ran the covert Kurdish program with the Shah and cut it off after the 1975 Algiers Accord."],
  ["ford", "Gerald Ford", "United States", "President 1974-1977", "nsdm324", "Approved offering Iran nuclear reprocessing in 1976. Rumsfeld was his defense secretary and Cheney his chief of staff."],
  ["carter", "Jimmy Carter", "United States", "President 1977-1981", "carterSotu", "Lost the Shah to revolution, faced the hostage crisis, and declared the Carter Doctrine to defend Gulf oil."],
  ["brzezinski", "Zbigniew Brzezinski", "United States", "National Security Adviser 1977-1981", "frus77afg", "Carter's national security adviser, who pushed covert aid to the Afghan rebels."],
  ["reagan", "Ronald Reagan", "United States", "President 1981-1989", "nsdd114", "Tilted toward Iraq in its war with Iran while his aides secretly sold arms to Iran. Expanded aid to the Afghan mujahideen."],
  ["rumsfeld", "Donald Rumsfeld", "United States", "Envoy 1983-84, Defense Secretary 2001-06", "ebb82", "Reagan's Middle East envoy who met Saddam in 1983, then George W. Bush's defense secretary during the invasion of Iraq."],
  ["bush41", "George H. W. Bush", "United States", "President 1989-1993", "aaas", "Sought better ties with Saddam in 1989, then led the 1991 coalition that drove Iraq out of Kuwait."],
  ["glaspie", "April Glaspie", "United States", "Ambassador to Iraq 1988-1990", "glaspie", "US ambassador who met Saddam eight days before he invaded Kuwait."],
  ["cheney", "Dick Cheney", "United States", "Defense Secretary 1989-93, VP 2001-09", "jwmaps", "Defense secretary in the Gulf War and later vice president, when he chaired the 2001 energy task force and pushed for the 2003 invasion."],
  ["powell", "Colin Powell", "United States", "Joint Chiefs 1989-93, Secretary of State 2001-05", "powell", "Top general in the Gulf War. As secretary of state he presented the WMD case to the UN in February 2003."],
  ["clinton", "Bill Clinton", "United States", "President 1993-2001", "ilaSign", "Kept Iraq under sanctions and no-fly zones, signed the Iraq Liberation Act and ordered Operation Desert Fox in 1998. Struck al-Qaeda after the embassy bombings."],
  ["bush43", "George W. Bush", "United States", "President 2001-2009", "war0319", "After 9/11 he invaded Afghanistan and then Iraq, citing weapons of mass destruction that were never found."],
  ["wolfowitz", "Paul Wolfowitz", "United States", "Deputy Defense Secretary 2001-2005", "pnac", "Signed the 1998 PNAC letter urging Saddam's removal and argued for targeting Iraq after 9/11."],
  ["tenet", "George Tenet", "United States", "CIA Director 1997-2004", "ssci04", "CIA director whose agency produced the flawed 2002 estimate on Iraqi weapons."],
  ["bremer", "L. Paul Bremer", "United States", "Head of the CPA 2003-2004", "cpa1", "Ran occupied Iraq in 2003 and 2004 and ordered de-Ba'athification and the army's dissolution."],
  ["obama", "Barack Obama", "United States", "President 2009-2017", "end11", "Ended the US combat mission in 2010, withdrew the last troops in 2011 and ordered the raid that killed bin Laden."],
  ["fahd", "King Fahd", "Saudi Arabia", "King 1982-2005", "c911", "Saudi king who let US troops into the kingdom in August 1990 after Iraq took Kuwait. Bin Laden, who opposed US forces on Saudi soil, turned against the Saudi rulers and the United States."],
  ["omar", "Mullah Omar", "Afghanistan", "Taliban leader 1994-2013", "c911p65", "Leader of the Taliban. Kept bin Laden under his protection even when other Taliban leaders objected, and broke a 1998 promise to the Saudis to expel him."],
  ["azzam", "Abdullah Azzam", "Al-Qaeda", "Cleric, died 1989", "c911p55", "Palestinian cleric whose sermons inspired bin Laden. Together they ran the Bureau of Services that sent Arab volunteers to Afghanistan."],
  ["turabi", "Hassan al-Turabi", "Sudan", "Islamist leader", "c911p56", "Head of Sudan's National Islamic Front, which shared power after a 1989 coup. Invited bin Laden to Sudan, then lost ground to President Bashir as outside pressure grew."],
  ["turki", "Prince Turki al-Faisal", "Saudi Arabia", "Saudi intelligence chief", "c911p115", "Head of Saudi intelligence. In 1998 he met Mullah Omar to press for bin Laden's expulsion."],
  ["blix", "Hans Blix", "UN", "UNMOVIC chief 2000-2003", "blix", "Chief UN weapons inspector who asked for more time in March 2003."],
  ["elbaradei", "Mohamed ElBaradei", "UN", "IAEA chief 1997-2009", "iaea", "Head of the UN nuclear agency, who reported that the Niger uranium documents were forged."],
  ["binladen", "Osama bin Laden", "Al-Qaeda", "1957-2011", "c911", "Saudi veteran of the Afghan jihad who founded al-Qaeda and ordered the 9/11 attacks."],
  ["zarqawi", "Abu Musab al-Zarqawi", "Al-Qaeda in Iraq", "Jordanian militant, killed 2006", "zdeath", "A Jordanian militant who became the most wanted man in occupied Iraq. He led a campaign of car bombs, assassinations, suicide attacks and hostage beheadings, bombed the UN headquarters in Baghdad, and set out to start a civil war between Shia and Sunni. Bin Laden called him the 'prince of al-Qaeda in Iraq'. US forces killed him in June 2006."]
